"""Integer algorithms used by kernel callers; explicit units and bounds."""
def register(topic,q,detail):
    topic('정수 Pow·Binary Exponentiation','라이브러리·알고리즘','lib/math/int_pow.c','int_pow',
      '거듭제곱을 exp번 곱하지 않고 지수의 bit를 사용해 계산량을 줄이는 실제 utility를 읽습니다.',
      'Result=1에서 시작하여 exp의 최하위 bit가 1이면 result에 base를 곱합니다. Exp를 오른쪽 한 bit shift하고 base를 제곱하여 다음 bit의 가중치를 준비합니다. Loop 수는 지수 bit 수에 비례합니다. Exp=0은 loop 없이 1이며 u64 overflow는 별도 error가 아니라 unsigned arithmetic 범위에서 잘립니다.',
      '고정 int_pow와 caller의 base/exp 범위를 읽고 3^5를 exp=5→2→1→0으로 추적합니다. 실제 값이 u64에 들어가는지 caller가 확인하며 arbitrary precision이나 modular exponentiation API로 혼동하지 않습니다.',
      'int_pow의 exp&1·exp>>=1·base*=base를 읽으세요.',
      q('int_pow(3,5)의 수학적 결과는?', '243', '15', 'Exp bit 101에 따라 3과 81을 result에 곱해 243입니다. 3×5와 거듭제곱을 구분합니다.'),
      q('exp=0이면 이 코드의 반환은?', '1', '0', 'Result=1이고 while(exp)에 들어가지 않습니다. Base가 0인 경우도 이 함수의 코드 반환은 1입니다.'),
      details=[detail('Bit 가중치','Base는 3→9→81로 제곱되고 exp의 각 1bit에 해당하는 항만 곱합니다. 지수 이진 표현의 자릿값을 반복 제곱으로 구현합니다.'),detail('파일 전체','파일의 유일한 함수·u64 결과와 unsigned exponent·GPL export·includes 및 pwm backlight에서 유래했다는 주석을 연결합니다. Overflow error branch는 없습니다.')])
    topic('정수 Sqrt·Shift-and-Subtract','라이브러리·알고리즘','lib/math/int_sqrt.c','int_sqrt',
      '부동소수점 없이 정수 제곱근의 바닥값을 얻는 과정에서 두 bit씩 처리하는 알고리즘을 봅니다.',
      '입력 0/1은 그대로 반환합니다. 가장 높은 set bit 위치를 짝수 위치로 맞춰 m을 시작하고 b=y+m과 입력을 비교합니다. Y를 한 bit shift한 뒤 충분하면 x에서 b를 빼고 y에 m을 더하며 m을 두 bit씩 내립니다. 반환은 floor(sqrt(x))입니다. 32bit long 구성의 int_sqrt64는 작은 입력에 기본 함수, 큰 u64에는 대응 loop를 사용합니다.',
      '고정 source에서 x=15/16/17의 결과를 비교하고 __fls·m>>=2·y 갱신을 표로 읽습니다. unsigned long 폭과 입력 함수 선택을 확인하며 real-valued sqrt의 소수 부분을 보존하는 API로 사용하지 않습니다.',
      'int_sqrt와 CONFIG BITS_PER_LONG<64의 int_sqrt64를 읽으세요.',
      q('int_sqrt(15)와 int_sqrt(16)의 결과는?', '3과 4', '4와 4', '반환은 floor입니다. 3²<=15<4²이고 16은 4²입니다.'),
      q('m은 반복마다 몇 bit 오른쪽으로 이동하는가?', '2bit', '항상 1bit', 'm>>=2입니다. 제곱근의 자릿값을 위한 두 input bit 단위 진행을 확인합니다.'),
      details=[detail('최상위 위치','__fls(x)&~1UL로 시작 위치를 짝수 bit에 맞춥니다. x<=1의 조기 반환은 0에 최상위 set bit helper를 호출하지 않는 의미도 있습니다.'),detail('파일 전체','C 파일은 기본 함수와 32bit long 조건의 u64 함수 및 각 export/include로 구성됩니다. Long이 64bit인 플랫폼에 같은 별도 본문이 항상 compile된다고 가정하지 않습니다.')])
    topic('Rational 근사·Continued Fraction과 Register 한계','라이브러리·알고리즘','lib/math/rational.c','rational_best_approximation',
      'PLL 같은 제한된 numerator/denominator register로 원하는 비율을 가장 가깝게 표현하는 원리를 봅니다.',
      'Helper는 Euclidean division n/d의 quotient를 continued fraction term으로 얻고 이전 두 convergent에서 새 numerator/denominator를 계산합니다. Register 상한을 넘으면 최대 가능한 semi-convergent와 이전 convergent의 가까움을 비교해 선택합니다. 두 output pointer에 결과를 씁니다. 입력·중간 unsigned long 연산 범위와 denominator의 의미는 caller가 확인해야 합니다.',
      '고정 source의 PLL 예처럼 원하는 비율과 최대 register 값을 넘기고 결과를 검증합니다. 22/7에서 다음 quotient·remainder를 손으로 계산하고 정확한 분수, 제한 때문에 근사한 분수, 분모 0 입력을 구분합니다.',
      'rational_best_approximation의 n/d·n%d·n2/d2·t·선택 조건을 읽으세요.',
      q('22/7의 첫 continued-fraction quotient와 remainder는?', '3과 1', '7과 3', '22=3×7+1입니다. 다음 iteration은 이전 denominator와 remainder인 7/1로 이어집니다.'),
      q('상한을 넘는 convergent가 나오면 언제나 단순 clamp하는가?', '이전 convergent와 가능한 semi-convergent를 비교한다', '분자와 분모를 독립적으로 잘라 끝낸다', 't를 두 register 상한으로 제한하고 가까움 비교 조건으로 선택합니다. 독립 clamp는 원래 비율의 근사성을 깨뜨릴 수 있습니다.'),
      details=[detail('작은 정확한 예','22/7에 max numerator=255, max denominator=31이면 이 정확한 분수가 범위에 들어갑니다. 첫 3/1 뒤 22/7 convergent와 remainder 0 종료를 따라 읽으세요.'),detail('파일 전체','파일은 한 public 함수·continued fraction 설명·PLL register 예·export·module 선언 및 includes입니다. 성공 여부를 errno로 반환하는 함수가 아니라 두 output pointer에 값을 기록합니다.')])
    topic('Reciprocal Divide·불변 Divisor의 Multiply/Shift','라이브러리·알고리즘','lib/math/reciprocal_div.c','reciprocal_value',
      '같은 divisor로 많은 입력을 나눌 때 준비 단계의 비용을 들여 빠른 경로를 곱셈과 shift로 바꿀 수 있습니다.',
      'reciprocal_value는 divisor에서 ceil(log2(d))와 multiplier·두 shift를 계산합니다. Header의 reciprocal_divide는 u64 곱의 높은 32bit와 correction shift로 unsigned quotient를 얻습니다. Divisor가 바뀌면 값을 다시 준비해야 합니다. Advanced 준비는 JIT tradeoff를 위한 별도 형식이며 ceil(log2(d))=32 등 지원 범위를 caller가 먼저 처리해야 합니다.',
      '고정 reciprocal_div.h와 두 준비 함수를 연결하고 nonzero u32 divisor를 고정하여 여러 dividend 결과를 일반 division과 비교합니다. 1/d의 부동소수점 근사값만 곱하는 방식이 아니라 정확한 integer correction 규약이며 d=0이나 advanced 범위를 무시하지 않습니다.',
      'reciprocal_value와 reciprocal_divide의 u64 product high·sh1/sh2를 읽으세요.',
      q('준비한 d=7로 a=100을 나누는 integer quotient는?', '14', '14.2857을 float로 반환', 'Unsigned integer division은 floor 100/7=14입니다. Helper 결과형은 u32이며 fractional quotient를 반환하지 않습니다.'),
      q('Divisor를 7에서 9로 바꾸고 기존 reciprocal을 그대로 쓰는가?', '새 divisor로 준비해야 한다', 'Multiplier는 모든 divisor에 공통이다', 'R.m/sh1/sh2는 d에서 계산한 상태입니다. 값 재사용은 divisor가 유지되는 slow/fast-path 계약에 달려 있습니다.'),
      details=[detail('성능 조건','한 번 나눌 때마다 reciprocal을 준비하면 이득이 줄어듭니다. Runtime-invariant divisor에서 준비 비용을 여러 fast-path 연산에 분산합니다.'),detail('Advanced 경계','Advanced는 큰 divisor와 prec에 따른 shift 범위 전제가 있습니다. WARN이 있다고 함수가 안전한 errno로 중단한다고 해석하지 말고 header의 exception 처리 예제를 읽습니다.')])
    topic('CORDIC·Shift 회전으로 I/Q 계산','라이브러리·알고리즘','lib/math/cordic.c','cordic_calc_iq',
      '부동소수점 삼각함수 없이 작은 회전과 shift/add로 cosine/sine에 대응하는 좌표를 근사하는 기술입니다.',
      'CORDIC은 입력 degree를 16bit fractional 고정소수점으로 바꾸고 각도를 정규화하여 ±90degree 근처 회전과 sign 보정으로 나눕니다. 18회 iteration에서 목표 theta와 누적 angle을 비교해 I/Q를 2^-iter 비율로 shift/add하고 arctan table을 더하거나 뺍니다. 초기 I는 gain 보정 상수이고 반환 I/Q는 2^16 scale입니다.',
      '고정 cordic.h의 scale·iteration·입력 각도 범위와 I/Q 설명을 연결합니다. 0/90degree의 기대 cosine/sine 방향을 먼저 예측하고 근사 오차와 integer rounding·입력 변환 범위를 확인합니다.',
      'cordic_calc_iq의 signx·valtmp·q>>iter·arctan_table과 header macro를 읽으세요.',
      q('Scale 2^16에서 실수 1에 대응하는 integer 값은?', '65536', '16', '2^16=65536입니다. 고정소수점 저장값과 실제 좌표를 구분합니다.'),
      q('valtmp로 새 I를 임시 보관하는 이유는?', 'Q 갱신에 아직 이전 I가 필요하기 때문에', '매번 두 배 길이 배열을 만들기 위해', 'Q 계산은 coord.i>>iter를 쓰고 뒤에 I=valtmp로 바꿉니다. 동시 좌표 변환에서 old/new 상태를 혼합하지 않는 순서입니다.'),
      details=[detail('초기 Gain','연속한 작은 회전은 길이 gain을 만들기 때문에 I를 CORDIC_ANGLE_GEN으로 시작합니다. 단순 (1,0)에 같은 unnormalized shift를 적용하는 것과 다릅니다.'),detail('파일 전체','C 파일은 18개 arctan table·단일 함수·export·module 선언입니다. Header는 scale/gain/iteration macro와 I/Q struct·prototype을 제공하며 input degree와 output fixed point가 같은 단위가 아닙니다.')])
    topic('Intlog·Lookup과 보간의 Fixed-point Log','라이브러리·알고리즘','lib/math/int_log.c','intlog2',
      '측정값의 logarithmic 크기를 float 없이 표현하려면 지수 부분·정규화된 significand와 scale을 구분해야 합니다.',
      'Intlog2는 최고 set bit를 msb로 얻고 value를 왼쪽 shift해 significand를 정규화합니다. 상위 bit로 table index를 고르고 남은 bit로 다음 entry까지 보간합니다. 반환은 log2(value)×2^24입니다. Intlog10은 log2 결과에 정수로 표현한 log10(2)를 곱해 shift합니다. 0은 정의되지 않아 WARN 후 0으로 나가지만 수학적 log가 0이라는 뜻은 아닙니다.',
      '고정 source의 table·msb·significand·interpolation과 반환 단위를 계산합니다. Positive u32 입력만 유효한 logarithm domain이고 결과를 그대로 일반 integer log라고 사용하지 말고 2^24 scale을 반영합니다.',
      'intlog2와 intlog10의 value==0·msb<<24·646456993 곱을 읽으세요.',
      q('정확한 2의 거듭제곱 8의 log2 fixed-point 기대 값은?', '3×2^24', '3byte 주소', 'log2(8)=3이며 결과는 2^24배 scale입니다. Significand가 1인 거듭제곱은 table entry와 보간의 기준점입니다.'),
      q('value=0에서 반환 0은 log2(0)=0을 의미하는가?', '아니며 undefined 입력의 경고 경로다', '수학적으로 항상 0이다', '원문은 log2(0) undefined라고 설명합니다. 오류 signal과 정상 값 표현이 겹치는 API에서는 입력 전제를 지켜야 합니다.'),
      details=[detail('보간 순서','곱셈을 먼저 하고 shift를 뒤에 두어 작은 ratio를 미리 정수 나눗셈으로 버리는 오차를 줄입니다. 중간 값의 bit 폭도 같이 확인합니다.'),detail('로그 밑 변환','log10(x)=log2(x)×log10(2) 관계를 integer multiplier로 구현합니다. 상수 숫자만 외우기보다 scale과 shift가 어떤 단위를 만드는지 읽으세요.')])
    topic('Prime Cache·Sieve·RCU와 Fallback','라이브러리·알고리즘','lib/math/prime_numbers.c','next_prime_number',
      '연속 소수 조회는 bitset sieve로 재사용할 수 있지만 확장 실패와 동시 reader의 수명도 처리해야 합니다.',
      'Prime library는 소수 위치 bit가 켜진 cache를 RCU로 조회하고 다음 값은 x+1부터 find_next_bit로 찾습니다. 필요하면 cache를 확장하여 알려진 소수의 배수를 지우는 sieve를 실행합니다. 새 cache는 mutex 아래 publish하고 이전 동적 cache는 RCU로 해제합니다. Allocation/크기 확장 실패는 trial-division fallback입니다.',
      '고정 source에서 next_prime_number·is_prime_number·expand·slow helper를 연결해 작은 입력을 비교합니다. Next는 현재 값보다 큰 소수이며 ULONG_MAX 경계·cache 범위·sleep 가능한 확장 context와 lifetime을 확인합니다. 암호학적 대형 소수 생성 API로 혼동하지 않습니다.',
      'next_prime_number의 RCU unlock 후 expand·x+1·fallback을 읽으세요.',
      q('next_prime_number(7)의 다음 소수는?', '11', '7', '탐색 시작은 x+1입니다. 현재 값이 이미 소수여도 그것을 그대로 반환하는 ceiling-prime 계약이 아닙니다.'),
      q('Cache allocation이 실패하면 반드시 즉시 모든 prime 조회 실패인가?', 'slow trial-division 경로로 전환한다', '항상 kernel panic이다', 'expand가 false면 slow_next_prime_number를 사용합니다. Cache 최적화와 기능 제공의 fallback을 구분합니다.'),
      details=[detail('Sieve','clear_multiples는 2*x 또는 범위에 맞춘 첫 배수부터 bit를 지웁니다. 원래 소수 자신의 bit까지 지우는 것과 다릅니다.'),detail('RCU와 Mutex','확장할 때는 RCU read lock을 놓고 allocation/update 경로로 갑니다. Reader 조회 보호와 sleep 가능한 writer 준비를 같은 lock 안에서 수행하는 것으로 설명하지 않습니다.')])
    topic('U64 곱셈 후 나눗셈·128bit 중간값','라이브러리·알고리즘','lib/math/div64.c','mul_u64_u64_div_u64',
      '최종 quotient는 64bit에 맞아도 곱셈 중간값이 넘을 수 있어 넓은 product를 유지해야 합니다.',
      'Helper는 작은 곱이면 일반 u64 division을 쓰고 큰 곱은 compiler u128 또는 32bit 조각의 부분 곱으로 high/low 128bit를 만듭니다. Divisor의 trailing zero를 이용해 줄일 수 있으면 축소 division, 아니면 정규화한 128/64 shift-subtract division을 합니다. Quotient가 u64 범위를 넘는 n_hi>=c는 -1을 u64로 반환합니다. c=0은 exception 전제로 정상 호출이 아닙니다.',
      '고정 source와 architecture override를 읽고 a*b/c의 중간 bit 폭을 먼저 계산합니다. 단순 a*b가 overflow한 뒤 나누는 식과 구분하고 divisor nonzero·반환 overflow sentinel 및 입력 범위 계약을 확인합니다.',
      'mul_u64_u64_div_u64의 u128/manual multiply·n_hi>=c·normalization loop를 읽으세요.',
      q('a=2^63,b=2,c=2이면 수학적 quotient는?', '2^63이며 중간 product는 2^64다', '중간 u64 wrap 0이 항상 올바른 quotient다', '곱은 u64를 넘지만 나눈 값은 표현 가능합니다. 128bit product를 유지하는 이유입니다.'),
      q('u64 함수가 overflow branch에서 -1을 반환하면 저장값은?', 'U64_MAX', 'signed -1을 저장할 수 있는 u64 음수', 'Unsigned 반환으로 변환된 -1은 모든 bit가 1입니다. Errno signed 함수와 이 sentinel을 구분합니다.'),
      details=[detail('Partial Product','u64를 high/low u32로 나누어 네 부분 곱과 carry를 합칩니다. 작은 register로 더 큰 정밀도의 연산을 구성하는 실제 사례입니다.'),detail('정규화','Divisor의 leading zeros로 align하여 high 부분과 비교·빼기를 반복하며 quotient bit를 세웁니다. 해당 public helper만으로 div64.c의 다른 모든 division API 해설이 완료된 것은 아닙니다.')])
